// Node crypto.createHmac 实现 HS256 签发与验签（正例）
const crypto = require('crypto');
const SECRET = Buffer.from('ch06-hs256-demo-secret');

function b64urlEncode(input) {
  const buf = Buffer.isBuffer(input) ? input : Buffer.from(String(input), 'utf8');
  return buf.toString('base64').replace(/=+$/g, '').replace(/\+/g, '-').replace(/\//g, '_');
}
function b64urlDecodeToBuffer(s) {
  const pad = s.length % 4 === 0 ? '' : '='.repeat(4 - (s.length % 4));
  return Buffer.from(s.replace(/-/g, '+').replace(/_/g, '/') + pad, 'base64');
}

function signHS256(secret, header, payload) {
  const h = b64urlEncode(JSON.stringify(header));
  const p = b64urlEncode(JSON.stringify(payload));
  const signingInput = h + '.' + p;
  const sig = crypto.createHmac('sha256', secret).update(signingInput).digest();
  return signingInput + '.' + b64urlEncode(sig);
}

function verifyHS256(secret, token) {
  const parts = token.split('.');
  if (parts.length !== 3) return { ok: false, reason: 'malformed' };
  const h = parts[0], p = parts[1], s = parts[2];
  const header = JSON.parse(b64urlDecodeToBuffer(h).toString('utf8'));
  if (header.alg !== 'HS256') return { ok: false, reason: 'alg-not-allowed' };
  const expected = crypto.createHmac('sha256', secret).update(h + '.' + p).digest();
  const got = b64urlDecodeToBuffer(s);
  // timingSafeEqual 要求等长，长度不等直接判失败（先比长度也是必要的一步）
  const ok = expected.length === got.length && crypto.timingSafeEqual(expected, got);
  if (!ok) return { ok: false, reason: 'bad-signature' };
  return { ok: true, payload: JSON.parse(b64urlDecodeToBuffer(p).toString('utf8')) };
}

const token = signHS256(SECRET, { alg: 'HS256', typ: 'JWT' },
  { sub: 'u1', role: 'editor', exp: 1700000100 });
const segs = token.split('.');
console.log('segments=' + segs.length);
console.log('signature_len_bytes=' + b64urlDecodeToBuffer(segs[2]).length);
console.log('signature_hex=' + b64urlDecodeToBuffer(segs[2]).toString('hex'));
const r = verifyHS256(SECRET, token);
console.log('verify_ok=' + r.ok);
console.log('claim_sub=' + r.payload.sub);
console.log('claim_role=' + r.payload.role);
